  static String str(String lang, String key, [List<String>? args]) {
    String text = _strings[lang]?[key] ?? _strings['id']?[key] ?? key;
    
    // Parse dual-language payloads like "ID: ... || EN: ..."
    if (text.contains('ID: ') && text.contains('|| EN: ')) {
      final parts = text.split('|| EN: ');
      if (lang == 'id') {
        text = parts[0].replaceAll('ID: ', '').trim();
      } else {
        text = parts[1].trim();
      }
    }

    if (args != null) {
      for (int i = 0; i < args.length; i++) {
        text = text.replaceAll('{'+i.toString()+'}', args[i]);
      }
    }
    return text;
  }
